	private void grdInputDetail_CellUpdated(object sender, ColumnActionEventArgs e)
	{
		//IL_001f: Unknown result type (might be due to invalid IL or missing references)
		try
		{
			grdInputDetail.UpdateData();
			GridEXRow r = grdInputDetail.CurrentRow;
			if (r == null || (int)r.RowType != 0 || r.Cells.Count <= 0)
			{
				return;
			}
			DateTime DocDate = Conversion.ToDateTime((object)txtDocdate.Value);
			if (e.Column.Key == "Quantity")
			{
				double Qty = Conversion.ToDouble((object)r.Cells["Quantity"].Value.ToString());
				Conversion.ToDouble((object)r.Cells["ItemUOMEquivalent"].Value.ToString());
				double Weight2 = Conversion.ToDouble(r.Cells["BalanceWeight"].Value) / Math.Abs(Conversion.ToDouble(r.Cells["BalanceQty"].Value)) * Qty;
				if (Conversion.ToDouble(r.Cells["BalanceWeight"].Value) < Weight2)
				{
					Weight2 = 0.0;
					r.Cells["Weight"].Value = 0;
					MessageBox.Show("Weight cannot greater than Balance Weight Please check!");
				}
				r.Cells["Weight"].Value = Weight2;
				int ItemId2 = Conversion.ToInt(r.Cells["ItemId"].Value);
				int JobLotId2 = Conversion.ToInt(r.Cells["JobLotId"].Value);
				int WareHouseId2 = Conversion.ToInt(r.Cells["WareHouseId"].Value);
				string CropYear2 = Conversion.ToString(r.Cells["CropYear"].Value);
				double rate2 = CommonServices.AvgRateOnlyForCGS(ItemId2, DocDate, 80, RecId, JobLotId2, 0, CropYear2, WareHouseId2);
				if (rate2 > 0.0)
				{
					double Rateuom2 = 1.0;
					double Rate2 = 0.0;
					if (dtAllUomWithItemId != null && dtAllUomWithItemId.Rows.Count > 0)
					{
						DataRow Row2 = dtAllUomWithItemId.AsEnumerable().FirstOrDefault((DataRow d) => d.Field<double>("Equivalent") == 40.0 && d.Field<int>("ItemId") == ItemId2);
						if (Row2 == null)
						{
							Row2 = dtAllUomWithItemId.AsEnumerable().FirstOrDefault((DataRow d) => d.Field<double>("Equivalent") == 1.0 && d.Field<int>("ItemId") == ItemId2);
						}
						if (Row2 != null)
						{
							Rateuom2 = Conversion.ToDouble(Row2["Equivalent"]);
							r.Cells["RateUOMId"].Value = Conversion.ToInt(Row2["Id"]);
							r.Cells["RateUOM"].Value = Conversion.ToString(Row2["UOMCode"]);
							r.Cells["RateUOMEquivalent"].Value = Rateuom2;
						}
					}
					Rate2 = rate2 * Rateuom2;
					r.Cells["Rate"].Value = Rate2.ToString();
					double Amount2 = ((Rateuom2 > 0.0) ? (Weight2 / Rateuom2 * Rate2) : 0.0);
					r.Cells["ItemAmount"].Value = Conversion.ToString((object)Amount2);
				}
				else
				{
					r.Cells["Rate"].Value = "0";
					r.Cells["RateUOMId"].Value = "0";
					r.Cells["RateUOM"].Value = "";
					r.Cells["RateUOMEquivalent"].Value = "0";
					r.Cells["ItemAmount"].Value = "0";
				}
			}
			if (e.Column.Key == "Weight")
			{
				double Weight = Conversion.ToDouble(r.Cells["Weight"].Value);
				if (Conversion.ToDouble(r.Cells["BalanceWeight"].Value) < Weight)
				{
					Weight = 0.0;
					r.Cells["Weight"].Value = 0;
					MessageBox.Show("Weight cannot greater than Balance Weight Please check!");
				}
				r.Cells["Weight"].Value = Weight;
				int ItemId = Conversion.ToInt(r.Cells["ItemId"].Value);
				int JobLotId = Conversion.ToInt(r.Cells["JobLotId"].Value);
				int WareHouseId = Conversion.ToInt(r.Cells["WareHouseId"].Value);
				string CropYear = Conversion.ToString(r.Cells["CropYear"].Value);
				double rate = CommonServices.AvgRateOnlyForCGS(ItemId, DocDate, 80, RecId, JobLotId, 0, CropYear, WareHouseId);
				if (rate > 0.0)
				{
					double Rateuom = 1.0;
					double Rate = 0.0;
					if (dtAllUomWithItemId != null && dtAllUomWithItemId.Rows.Count > 0)
					{
						DataRow Row = dtAllUomWithItemId.AsEnumerable().FirstOrDefault((DataRow d) => d.Field<double>("Equivalent") == 40.0 && d.Field<int>("ItemId") == ItemId);
						if (Row == null)
						{
							Row = dtAllUomWithItemId.AsEnumerable().FirstOrDefault((DataRow d) => d.Field<double>("Equivalent") == 1.0 && d.Field<int>("ItemId") == ItemId);
						}
						if (Row != null)
						{
							Rateuom = Conversion.ToDouble(Row["Equivalent"]);
							r.Cells["RateUOMId"].Value = Conversion.ToInt(Row["Id"]);
							r.Cells["RateUOM"].Value = Conversion.ToString(Row["UOMCode"]);
							r.Cells["RateUOMEquivalent"].Value = Rateuom;
						}
					}
					Rate = rate * Rateuom;
