			if (dtInput.Rows.Count <= 0)
			{
				return;
			}
			for (int i = 0; i < dtInput.Rows.Count; i++)
			{
				bool flag = false;
				GridEXRow[] rows = grdInputDetail.GetRows();
				foreach (GridEXRow item in rows)
				{
					if (Conversion.ToInt(dtInput.Rows[i]["Id"]) == Conversion.ToInt(item.Cells["JobOrderInPutId"].Value))
					{
						flag = true;
					}
				}
				if (!flag && !flag)
				{
					table.Rows.Add(0, dtInput.Rows[i]["Id"], dtInput.Rows[i]["RefDocumentTypeId"], dtInput.Rows[i]["RefDocumentType"], dtInput.Rows[i]["RefDocIdNo"], dtInput.Rows[i]["RefDocSubIdNo"], Conversion.ToDateTime(dtInput.Rows[i]["RefDocDate"]).ToString("dd-MMM-yyyy"), dtInput.Rows[i]["RefDocNo"], dtInput.Rows[i]["WareHouseId"], dtInput.Rows[i]["WareHouseName"], dtInput.Rows[i]["ItemId"], dtInput.Rows[i]["ItemName"], dtInput.Rows[i]["PackUomId"], dtInput.Rows[i]["PackUom"], dtInput.Rows[i]["PackUomEquivalent"], dtInput.Rows[i]["CropYear"], dtInput.Rows[i]["JobLotId"], dtInput.Rows[i]["JobLotDescription"], dtInput.Rows[i]["PackingTypeId"], dtInput.Rows[i]["PackTypeDesc"], Math.Abs(Conversion.ToDouble(dtInput.Rows[i]["BalQty"])), dtInput.Rows[i]["BalWeight"], Math.Abs(Conversion.ToDouble(dtInput.Rows[i]["BalQty"])), dtInput.Rows[i]["BalWeight"], dtInput.Rows[i]["ItemRate"], dtInput.Rows[i]["RateUomId"], dtInput.Rows[i]["RateUOM"], dtInput.Rows[i]["RateUomEquivalent"], dtInput.Rows[i]["BalAmount"], "");
				}
			}
			grdInputDetail.DataSource = table;
			grdInputDetail.RetrieveStructure();
			grdInputSettings();
			((Control)(object)CmbJobOrderNo).Enabled = false;
