			obj.BranchesId = UserAccount.BranchesId;
			obj.FinancialYearId = clsGlobalVariables.ActiveYr.Id;
			if (txtFromdateHistory.Checked)
			{
				obj.FromDate = Conversion.ToDateTime((object)txtFromdateHistory.Value);
			}
			if (txtToDateHistory.Checked)
			{
				obj.ToDate = Conversion.ToDateTime((object)txtToDateHistory.Value);
			}
			obj.FromDocNo = Conversion.ToInt((object)txtFromNoHistory.Text);
			obj.ToDocNo = Conversion.ToInt((object)txtToDocNoHistory.Text);
			obj.JobOrderId = Conversion.ToInt(CmbJobOrderInputHistory.Value);
			obj.RefDocumentTypeId = 401;
			DataTable dthis = InvFoodProduction.ProductionFormHistory(obj);
			if (dthis.Rows.Count > 0)
			{
				DataTable dtgrdinput = new DataTable();
				dtgrdinput.Columns.Add("Id");
				dtgrdinput.Columns.Add("DocSrNo", typeof(int));
				dtgrdinput.Columns.Add("DocDate", typeof(DateTime));
				dtgrdinput.Columns.Add("JobOrderNo");
				dtgrdinput.Columns.Add("PlantName");
				dtgrdinput.Columns.Add("EntryType");
				dtgrdinput.Columns.Add("Remarks");
				dtgrdinput.Columns.Add("IsApproved");
				dtgrdinput.Columns.Add("StartDate", typeof(DateTime));
				dtgrdinput.Columns.Add("EndDate", typeof(DateTime));
				dtgrdinput.Columns.Add("EntryDate", typeof(DateTime));
				dtgrdinput.Columns.Add("EntryUser", typeof(string));
				dtgrdinput.Columns.Add("ModifyDate", typeof(DateTime));
				dtgrdinput.Columns.Add("ModifyUser", typeof(string));
				dtgrdinput.Columns.Add("PlanStatus", typeof(string));
				dtgrdinput.Columns.Add("WagesId", typeof(int));
				dtgrdinput.Clear();
				for (int i = 0; i < dthis.Rows.Count; i++)
				{
					if (Conversion.ToInt(dthis.Rows[i]["DocumentTypeId"]) == 80)
					{
						dtgrdinput.Rows.Add(dthis.Rows[i]["Id"], dthis.Rows[i]["DocCode"], Conversion.ToDateTime(dthis.Rows[i]["DocDate"]).ToString("dd-MMM-yyyy"), dthis.Rows[i]["InvJobOrderNo"], dthis.Rows[i]["PlantName"], dthis.Rows[i]["EntryType"], dthis.Rows[i]["MainRemarks"], dthis.Rows[i]["JobOrderApprovedStatus"], Conversion.ToDateTime(dthis.Rows[i]["StartDate"]).ToString("dd-MMM-yyyy"), Conversion.ToDateTime(dthis.Rows[i]["EndDate"]).ToString("dd-MMM-yyyy"), dthis.Rows[i]["EntryDate"], dthis.Rows[i]["EntryUser"], dthis.Rows[i]["ModifyDate"], dthis.Rows[i]["ModifyUser"], dthis.Rows[i]["PlanStatus"], dthis.Rows[i]["WagesId"]);
					}
				}
				grdInputHistory.DataSource = dtgrdinput;
				grdInputHistory.RetrieveStructure();
				GridInputSetting();
			}
			else
			{
				grdInputHistory.DataSource = null;
			}
		}
		catch (Exception ex)
		{
			MessageBox.Show(ex.Message, "Message Error", MessageBoxButtons.OK, MessageBoxIcon.Hand);
		}
	}

