			grdByProduct.UpdateData();
			GridEXRow r = grdByProduct.CurrentRow;
			if (r == null || (int)r.RowType != 0 || r.Cells.Count <= 0)
			{
				return;
			}
			if (e.Column.Key == "Quantity")
			{
				double Qty = Conversion.ToDouble((object)r.Cells["Quantity"].Value.ToString());
				Conversion.ToDouble((object)r.Cells["ItemEquivalent"].Value.ToString());
				double Weight2 = Conversion.ToDouble(r.Cells["BalanceWeight"].Value) / Math.Abs(Conversion.ToDouble(r.Cells["BalanceQty"].Value)) * Qty;
				if (Conversion.ToDouble(r.Cells["BalanceWeight"].Value) < Weight2)
				{
					Weight2 = 0.0;
					MessageBox.Show("Weight cannot greater than Balance Weight Please check!");
				}
				r.Cells["Weight"].Value = Weight2;
				r.Cells["GrossWeight"].Value = Weight2;
				double Rate2 = Conversion.ToDouble(r.Cells["Rate"].Value);
				double Rateuom2 = Conversion.ToDouble(r.Cells["RateEquivalent"].Value);
				double Amount2 = ((Rateuom2 > 0.0) ? (Weight2 / Rateuom2 * Rate2) : 0.0);
				r.Cells["ItemAmount"].Value = Conversion.ToString((object)Amount2);
			}
			if (e.Column.Key == "Weight")
			{
				double Weight = Conversion.ToDouble(r.Cells["Weight"].Value);
				if (Conversion.ToDouble(r.Cells["BalanceWeight"].Value) < Weight)
				{
					Weight = 0.0;
					MessageBox.Show("Weight cannot greater than Balance Weight Please check!");
				}
				r.Cells["Weight"].Value = Weight;
				r.Cells["GrossWeight"].Value = Weight;
				double Rate = Conversion.ToDouble(r.Cells["Rate"].Value);
				double Rateuom = Conversion.ToDouble(r.Cells["RateEquivalent"].Value);
				double Amount = ((Rateuom > 0.0) ? (Weight / Rateuom * Rate) : 0.0);
				r.Cells["ItemAmount"].Value = Conversion.ToString((object)Amount);
			}
			grdOutPutDetail.UpdateData();
		}
		catch (Exception ex)
		{
			MessageBox.Show(ex.Message);
		}
	}

