	private void LoadOutPutDataFromJobOrder()
	{
		try
		{
			DataTable dtLoadOutPutFromJobOrder = LoadOutPut.dtIssuance;
			if (dtLoadOutPutFromJobOrder.Rows.Count <= 0)
			{
				return;
			}
			for (int i = 0; i < dtLoadOutPutFromJobOrder.Rows.Count; i++)
			{
				bool flag = false;
				GridEXRow[] rows = grdByProduct.GetRows();
				foreach (GridEXRow item in rows)
				{
					if (Conversion.ToInt(dtLoadOutPutFromJobOrder.Rows[i]["Id"]) == Conversion.ToInt(item.Cells["OutPutIdFromJobOrder"].Value))
					{
						flag = true;
					}
				}
				if (!flag && !flag)
				{
					tableByProduct.Rows.Add(0, dtLoadOutPutFromJobOrder.Rows[i]["Id"], dtLoadOutPutFromJobOrder.Rows[i]["EntryType"], dtLoadOutPutFromJobOrder.Rows[i]["WareHouseId"], dtLoadOutPutFromJobOrder.Rows[i]["ItemId"], dtLoadOutPutFromJobOrder.Rows[i]["ItemName"], dtLoadOutPutFromJobOrder.Rows[i]["PackUomId"], dtLoadOutPutFromJobOrder.Rows[i]["OuterPackUom"], dtLoadOutPutFromJobOrder.Rows[i]["OuterPackUomEquivalent"], dtLoadOutPutFromJobOrder.Rows[i]["CropYear"], dtLoadOutPutFromJobOrder.Rows[i]["JobLotId"], dtLoadOutPutFromJobOrder.Rows[i]["InvPackingTypeId"], Math.Abs(Conversion.ToDouble(dtLoadOutPutFromJobOrder.Rows[i]["BalQty"])), dtLoadOutPutFromJobOrder.Rows[i]["BalWeight"], 0, 0, dtLoadOutPutFromJobOrder.Rows[i]["BalWeight"], Math.Abs(Conversion.ToDouble(dtLoadOutPutFromJobOrder.Rows[i]["BalQty"])), dtLoadOutPutFromJobOrder.Rows[i]["BalWeight"], dtLoadOutPutFromJobOrder.Rows[i]["NetRate"], dtLoadOutPutFromJobOrder.Rows[i]["RateUomId"], dtLoadOutPutFromJobOrder.Rows[i]["RateUOM"], dtLoadOutPutFromJobOrder.Rows[i]["RateUomEquivalent"], dtLoadOutPutFromJobOrder.Rows[i]["BalNetAmount"], dtLoadOutPutFromJobOrder.Rows[i]["RemarksDetail"], 0);
				}
			}
			grdByProduct.DataSource = tableByProduct;
			grdByProduct.RetrieveStructure();
			grdOutPutSettings();
			((Control)(object)CmbJobOrderNoOutput).Enabled = false;
		}
		catch (Exception ex)
		{
			MessageBox.Show(ex.Message);
		}
	}

