	private void grddetailPackingMaterial_CellUpdated(object sender, ColumnActionEventArgs e)
	{
		//IL_001f: Unknown result type (might be due to invalid IL or missing references)
		try
		{
			grddetailPackingMaterial.UpdateData();
			GridEXRow r = grddetailPackingMaterial.CurrentRow;
			if (r != null && (int)r.RowType == 0 && r.Cells.Count > 0)
			{
				if (e.Column.Key == "ItemQty")
				{
					double Qty = Conversion.ToDouble((object)r.Cells["ItemQty"].Value.ToString());
					double BalQty = Conversion.ToDouble((object)r.Cells["BalQty"].Value.ToString());
					if (BalQty > 0.0 && BalQty < Qty)
					{
						r.Cells["ItemQty"].Value = 0;
						Qty = 0.0;
						MessageBox.Show("Qty cannot greater than BalanceQty Please check!");
					}
					double Rate2 = Conversion.ToDouble((object)r.Cells["ItemRate"].Value.ToString());
					double Amount2 = Qty * Rate2;
					r.Cells["Amount"].Value = Amount2;
				}
				if (e.Column.Key == "ItemRate")
				{
					double num = Conversion.ToDouble((object)r.Cells["ItemQty"].Value.ToString());
					double Rate = Conversion.ToDouble((object)r.Cells["ItemRate"].Value.ToString());
					double Amount = num * Rate;
					r.Cells["Amount"].Value = Amount;
				}
				grdOutPutDetail.UpdateData();
			}
			grddetailPackingMaterial.UpdateData();
		}
		catch (Exception ex)
		{
			MessageBox.Show(ex.Message);
		}
	}

