	private void LoadPackingMaterialDataFromJobOrder()
	{
		try
		{
			DataTable dtLoadPMFromJobOrder = LoadPackingMaterial.dtIssuance;
			if (dtLoadPMFromJobOrder.Rows.Count > 0)
			{
				for (int i = 0; i < dtLoadPMFromJobOrder.Rows.Count; i++)
				{
					bool flag = false;
					GridEXRow[] rows = grddetailPackingMaterial.GetRows();
					foreach (GridEXRow item in rows)
					{
						if (Conversion.ToInt(dtLoadPMFromJobOrder.Rows[i]["Id"]) == Conversion.ToInt(item.Cells["JobOrderPackingMaterialId"].Value))
						{
							flag = true;
						}
					}
					if (!flag && !flag)
					{
						tablePackingMaterial.Rows.Add(0, dtLoadPMFromJobOrder.Rows[i]["Id"], Conversion.ToDateTime((object)txtdocdatePackingMaterial.Value), 0, dtLoadPMFromJobOrder.Rows[i]["InvProductionJobOrderId"], Conversion.ToInt((object)0), Conversion.ToString((object)""), dtLoadPMFromJobOrder.Rows[i]["WareHouseId"], dtLoadPMFromJobOrder.Rows[i]["ItemId"], dtLoadPMFromJobOrder.Rows[i]["PMItemName"], dtLoadPMFromJobOrder.Rows[i]["BrandId"], dtLoadPMFromJobOrder.Rows[i]["BrandName"], dtLoadPMFromJobOrder.Rows[i]["BrandUomId"], dtLoadPMFromJobOrder.Rows[i]["BrandUom"], dtLoadPMFromJobOrder.Rows[i]["balQty"], dtLoadPMFromJobOrder.Rows[i]["balQty"], dtLoadPMFromJobOrder.Rows[i]["Rate"], dtLoadPMFromJobOrder.Rows[i]["balAmount"], dtLoadPMFromJobOrder.Rows[i]["pmRemarks"]);
					}
