			{
				((UltraGridBase)cmbWIPAcConsumption).DataSource = null;
				((UltraGridBase)cmbWIPItemConsumption).DataSource = null;
			}
			GetPlantFeeder(Pro.Id);
		}
		catch (Exception ex)
		{
			MessageBox.Show(ex.Message);
		}
	}

