			return false;
		}
		return true;
	}

	private void BtnAddConsumption_Click(object sender, EventArgs e)
	{
		try
		{
			if (!FormValidationOfDetailConsumption())
			{
				return;
			}
			if (tableConsumption.Rows.Count > 0)
			{
				for (int i = 0; i < tableConsumption.Rows.Count; i++)
				{
					if (Conversion.ToInt(tableConsumption.Rows[i]["RefDocumentTypeId"]) > 0)
					{
						throw new Exception("Record cannot be add in grid because record already add from loader");
					}
				}
			}
			int ItemId = Conversion.ToInt(CmbItemNameConsumption.Value);
			string ItemName = "";
			string ItemCode = "";
			if (ItemId > 0)
			{
				ItemName = Conversion.ToString(((UltraDropDownBase)CmbItemNameConsumption).SelectedRow.Cells["ItemName"].Value);
				ItemCode = Conversion.ToString(((UltraDropDownBase)CmbItemNameConsumption).SelectedRow.Cells["ItemCode"].Value);
			}
			int PackUomId = Conversion.ToInt(cmbPackUomConsumption.Value);
			string PackUomCode = "";
			double PackUomEquivalent = 0.0;
			if (PackUomId > 0)
			{
				PackUomCode = Conversion.ToString((object)((Control)(object)cmbPackUomConsumption).Text);
				PackUomEquivalent = Conversion.ToDouble(((UltraDropDownBase)cmbPackUomConsumption).SelectedRow.Cells[2].Value);
			}
			int RateUomId = Conversion.ToInt(CmbRateUomConsumption.Value);
			string RateUomCode = "";
			double RateUomEquivalent = 0.0;
			if (RateUomId > 0)
			{
				RateUomCode = Conversion.ToString((object)((Control)(object)CmbRateUomConsumption).Text);
				RateUomEquivalent = Conversion.ToDouble(((UltraDropDownBase)CmbRateUomConsumption).SelectedRow.Cells[2].Value);
			}
			tableConsumption.Rows.Add(0, 0, 0, 0, 0, 0, Conversion.ToInt(cmbWarehouseConsumption.Value), ((Control)(object)cmbWarehouseConsumption).Text, ItemId, ItemName, ItemCode, PackUomId, PackUomCode, PackUomEquivalent, ((Control)(object)CmbCropYearConsumption).Text, Conversion.ToInt(CmbJobLotConsumption.Value), ((Control)(object)CmbJobLotConsumption).Text, Conversion.ToInt(CmbPackingTypeConsumption.Value), ((Control)(object)CmbPackingTypeConsumption).Text, Conversion.ToDouble((object)txtBalanceQtyConsumption.Text), Conversion.ToDouble((object)txtBalanceWeightConsumption.Text), Conversion.ToDouble((object)txtItemQtyConsumption.Text), Conversion.ToDouble((object)txtNetWeightConsumption.Text), Conversion.ToDouble((object)txtRateConsumption.Text), Conversion.ToDouble((object)txtRateConsumption.Text), RateUomId, RateUomCode, RateUomEquivalent, Conversion.ToDouble((object)txtAmountConsumption.Text), txtRemarksDetailConsumption.Text);
			grdConsumption.DataSource = tableConsumption;
			grdConsumption.RetrieveStructure();
			grdConsumptionsettings();
			ResetConsumptionDetail();
			cmbWarehouseConsumption.Focus();
		}
		catch (Exception ex)
		{
			MessageBox.Show(ex.Message);
		}
	}

